const logoTapArea = document.getElementById("brand-logo-tap-area");
if(logoTapArea){
  logoTapArea.addEventListener("click", ()=>{
    const now = Date.now();
    if(!state.logoTapTimes || now - (state.lastLogoTapTime||0) > 1200) state.logoTapTimes = [];
    state.logoTapTimes.push(now);
    state.lastLogoTapTime = now;
    if(state.logoTapTimes.length >= 5){
      state.logoTapTimes = [];
      showAdminEntryChooser();
    }
  });
}
