try{
  const roleR = localGet("my-role");
  if(roleR && roleR.value === "hq"){
    state.role = "hq";
    await loadStoreList();
    await loadAllForStore(state.store);
    render();
    return;
  }
  if(roleR && roleR.value === "franchise"){
    const fidR = localGet("my-franchise-id");
    const fid = fidR ? fidR.value : null;
    if(fid){
      try{
        const { data } = await db.from('franchises').select('id,name,username').eq('id', fid).maybeSingle();
        if(data){
          state.role = "franchise";
          state.franchiseId = data.id;
          state.franchiseName = data.name;
          await loadStoreList(null, data.id);
          await loadAllForStore(state.store);
          render();
          return;
        }
      }catch(e){}
    }
  }
}catch(e){}
